(function (root, factory) {
  'use strict';
  const courseData = factory();
  if (typeof module === 'object' && module.exports) module.exports = courseData;
  if (root && root.document) root.STEMPlusCourseData = courseData;
}(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';
  const q = (prompt, correct, wrong1, wrong2, explain) => ({ prompt, correct, wrong: [wrong1, wrong2], explain });
  const practice = 'https://webshell.cylabacademy.org/';
  const manual = 'https://www.gnu.org/software/bash/manual/bash.html';
  const primer = 'https://primer.picoctf.org/';
  const expandedLessonCopy = {
    'shell-prompts-commands-arguments-and-exit-status': {
      subtitle: 'Learn how Bash separates a command name from its arguments, launches the requested program, and reports whether that program succeeded. This mental model helps you read terminal instructions accurately and prevents a failed CTF step from silently damaging everything that follows.',
      key: [['Shell', 'A shell is a program that reads command language, prepares the requested input and output, and starts other programs. Bash is both an interactive shell and a scripting language, so the same rules apply at the prompt and inside a solve script.'], ['Argument', 'An argument is one value passed to a command after its name. Bash preserves the argument boundary, while the receiving command decides whether that value is a filename, option, pattern, host, or something else.'], ['Exit status', 'An exit status is the integer a command returns when it finishes. Zero conventionally means success, while a nonzero value signals a failure or special condition that a script should inspect.']],
      good: 'The prompt is interface text that shows the shell is ready; it is not part of the command. When a guide shows `$ file artifact.bin`, type only `file artifact.bin`, and remember that output printed afterward is also not another command.',
      study: 'Run harmless commands with zero, one, and several arguments, then use `printf` to make each boundary visible. Immediately inspect `$?` after both a successful command and a deliberate failure, because running another command replaces the status you wanted to examine.',
      apply: 'In an authorized picoCTF workspace, imagine a decoder fails because its input has the wrong format, but the script continues and submits an empty result. Check the decoder’s exit status, stop on failure, and print a useful diagnostic so the team knows which step and artifact need review.'
    },
    'quoting-expansion-and-command-boundaries': {
      subtitle: 'Learn what Bash expands before a command runs and how quoting controls those changes. Correct quoting keeps filenames, patterns, and captured output in the exact argument boundaries you intended.',
      key: [['Expansion', 'Expansion is the shell phase that replaces syntax such as `$name`, `*.txt`, or `$(command)` before execution. The receiving program sees only the resulting arguments, so an unexpected expansion can completely change what the command does.'], ['Single quotes', 'Single quotes preserve every enclosed character literally until the closing quote. Use them when text such as `$`, `*`, or backslashes must reach a command unchanged.'], ['Double quotes', 'Double quotes preserve spaces and most literal characters while still allowing variable and command substitution. They are the usual safe choice around a variable such as `"$file"` because its value remains one argument.']],
      good: 'An unquoted variable can split on whitespace and expand wildcard characters, turning one intended filename into several arguments. Quote `"$variable"` unless splitting is deliberate, and inspect an unfamiliar expansion before using it with a command that changes files.',
      study: 'Before running each example, write the exact argument list Bash should produce for spaces, globs, single quotes, double quotes, and command substitution. Verify your prediction with bracketed `printf` output, then explain which expansion happened and which quote prevented it.',
      apply: 'An authorized challenge provides an artifact named `challenge files/flag one.txt`. Build and explain a command that reads that exact path, then show how the unquoted version would split the name and point at the wrong files.'
    },
    'help-man-type-which-and-history': {
      subtitle: 'Use the terminal’s own documentation to identify a command, understand its options, and verify what Bash will actually execute. This is safer and faster than pasting an unexplained command into a competition shell.',
      key: [['Builtin', 'A builtin is a command implemented inside Bash rather than in a separate executable file. Builtins such as `cd` must affect the current shell, which is why their documentation is normally available through `help`.'], ['man page', 'A man page is a structured local reference describing a command’s purpose, syntax, options, files, and related tools. It is especially useful when you need the exact meaning of a flag without leaving the terminal.'], ['type', '`type` is a Bash builtin that reports how the shell will resolve a command name. It distinguishes aliases, functions, builtins, hashed paths, and external executables so you know what will actually run.']],
      good: 'Use `help` for Bash builtins, `man` for most external commands, and `command --help` for a quick option summary. Treat shell history as sensitive because copied tokens, passwords, paths, or flags can remain stored after the visible session ends.',
      study: 'For every unfamiliar command, identify whether it is a builtin or executable, open the appropriate help, find one relevant option, and test it on disposable input. Summarize the option in your own words instead of memorizing a copied command line.',
      apply: 'During an authorized competition, a teammate remembers `grep` but not the option that includes line numbers. Use local documentation to find and test the option, then use `type` to confirm the resolved command before applying it to challenge notes.'
    },
    'pwd-cd-and-paths': {
      subtitle: 'Understand how the current directory changes the meaning of every relative path. Confirming your location before reading, writing, or deleting a file prevents work on the wrong artifact.',
      key: [['Working directory', 'The working directory is the folder Bash uses as the starting point for relative paths. Each shell process has its own current location, and `pwd` makes that hidden state visible.'], ['Absolute path', 'An absolute path starts at the filesystem root, such as `/home/learner/challenge`. Its meaning does not change when the working directory changes, so it is useful when a script must identify one exact location.'], ['Relative path', 'A relative path is interpreted from the current working directory. It is convenient and short, but the same text can name a different file after `cd`, which makes location checks important.']],
      good: 'A single dot means the current directory, two dots mean its parent, and `~` expands to the current user’s home directory. `cd -` returns to the previous directory, which is useful when comparing two challenge locations without losing your place.',
      study: 'Draw a small directory tree and predict the result of several `cd` commands and relative paths before checking with `pwd`. For each path, also write the equivalent absolute path so you can see exactly which part depends on location.',
      apply: 'A picoCTF bundle contains several nested directories with duplicate `output.txt` names. Navigate only inside the extracted challenge workspace, use `pwd` and an absolute path to prove which artifact you selected, and record that path before analysis.'
    },
    'ls-stat-file-and-hidden-entries': {
      subtitle: 'Build a reliable inventory of filenames, hidden entries, permissions, sizes, timestamps, and actual content types. These observations turn an unfamiliar challenge directory into evidence for choosing the next tool.',
      key: [['Hidden entry', 'A hidden entry on Unix is simply a filename whose first character is a dot. Normal `ls` output omits it, but the file has no automatic secrecy or special protection.'], ['stat', '`stat` reports detailed filesystem metadata for a path, including size, permissions, timestamps, and identifiers. These facts help compare artifacts, but timestamps and ownership alone do not prove who created the content.'], ['file', '`file` examines signatures and structural patterns inside content to estimate its format. It is more trustworthy than a filename extension, though its result is still an identification clue rather than a guarantee that a file is safe.']],
      good: '`ls -a` reveals dotfiles and `ls -l` shows a long listing with permissions, ownership, size, and time information. Neither proves a content type, so use `file` before choosing an archive, image, or executable-specific parser.',
      study: 'Create a directory containing ordinary, hidden, renamed, and differently sized files. Inventory it with `ls -la`, compare selected entries with `stat`, run `file`, and state which question each command answered.',
      apply: 'An authorized challenge directory appears empty in a normal listing. Reveal hidden entries, compare their metadata, identify the real archive by content rather than extension, and explain why the other observations are useful but not conclusive.'
    },
    'mkdir-touch-cp-mv-and-safe-removal': {
      subtitle: 'Create a controlled workspace, preserve original challenge artifacts, and organize derived files without accidental data loss. Safe file handling makes every transformation reproducible and reversible.',
      key: [['mkdir', '`mkdir` creates a directory, while `mkdir -p` can create missing parent directories and tolerate an existing destination. A dedicated directory keeps one challenge’s originals, notes, and derived files from becoming mixed with unrelated work.'], ['cp', '`cp` creates a new file or directory entry while leaving the source in place. Use it to make a working copy so decoding, renaming, or extraction does not alter the original evidence.'], ['mv', '`mv` moves a path to another location or renames it. Because the original name disappears after a successful move, verify both source and destination before using it on important artifacts.']],
      good: '`rm` normally removes files without a recycle bin or simple undo. Avoid broad wildcards, confirm `pwd`, list the exact targets, and perform experiments on disposable copies rather than the only challenge download.',
      study: 'Create a temporary challenge-style folder, copy an artifact into a work directory, rename only the copy, and list source and destination after each action. Practice removal solely on files you created for the exercise, stating the target before executing the command.',
      apply: 'You receive `evidence.zip` from an authorized picoCTF challenge. Preserve the download, record its checksum, create a clearly named workspace, copy the archive there, and perform all listing and extraction on that copy so the original remains available for comparison.'
    },
    'stdin-stdout-stderr-and-file-descriptors': {
      subtitle: 'Treat ordinary input, successful output, and diagnostics as three separate streams. Knowing where each stream goes lets you build clean pipelines and keep useful error evidence.',
      key: [['stdin', 'Standard input is file descriptor 0 and is the stream from which a command normally reads. It may come from the keyboard, a file redirection, or the stdout of an earlier command.'], ['stdout', 'Standard output is file descriptor 1 and carries a command’s normal result. Redirecting or piping stdout lets another tool consume that result without copying it manually.'], ['stderr', 'Standard error is file descriptor 2 and carries diagnostics, warnings, and error messages. Keeping it separate prevents a parser from mistaking an error message for valid challenge data.']],
      good: 'Separating stdout from stderr lets a pipeline transform valid output while warnings remain visible or are saved to a different log. The exit status still matters because an empty stdout stream does not by itself explain whether the command succeeded.',
      study: 'Run a harmless command that produces both a normal line and a deliberate error. Redirect stdout and stderr to separate files, inspect both, and draw the stream path from the command to each destination.',
      apply: 'An authorized decoder writes candidate flags to stdout and malformed-record warnings to stderr. Save the candidates for a later filter, preserve the warning log for troubleshooting, and check the exit status before trusting either result.'
    },
    'redirecting-input-output-and-errors': {
      subtitle: 'Connect command streams to files without confusing replacement, appending, input, and error redirection. A precise redirection plan protects earlier results and keeps diagnostics available.',
      key: [['>', '`>` sends stdout to a file after truncating that destination. It is appropriate when intentionally creating a fresh result, but it can erase useful content before the command itself succeeds.'], ['>>', '`>>` sends stdout to the end of a file while preserving existing content. It is useful for a cumulative solve log when each run should add another record.'], ['2>', '`2>` sends only file descriptor 2, stderr, to a file. Normal stdout remains available for the terminal or the next pipeline stage, so errors do not contaminate valid data.']],
      good: 'Bash establishes redirections before launching the command, which means a mistaken `>` can empty an existing file even if execution later fails. Confirm the destination and use disposable files while learning each operator.',
      study: 'With a set of disposable files, create output with `>`, append with `>>`, provide input through `<`, and separate stdout from stderr. Inspect the file size and contents after every step, then predict what a repeated run will do.',
      apply: 'A competition helper records one authorized challenge result per run and must never erase earlier entries. Append successful output to the solve log, send errors to a separate diagnostic file, and verify that a failed run does not add a misleading result.'
    },
    'pipes-tee-and-command-substitution': {
      subtitle: 'Combine focused commands by passing streams between them while preserving useful intermediate evidence. Build and verify each stage before compressing the workflow into a pipeline.',
      key: [['Pipe', 'The `|` operator connects the stdout of the command on its left to the stdin of the command on its right. Each stage should perform one clear transformation so you can reason about where incorrect output entered the chain.'], ['tee', '`tee` copies stdin both to stdout and to one or more files. It lets a pipeline continue while saving an intermediate stream for inspection or later reproduction.'], ['Command substitution', 'The `$(command)` form captures a command’s stdout and inserts it into the surrounding command line. Quote the substitution when its output must remain one argument, and avoid using it for large or binary streams.']],
      good: 'A pipeline normally reports the exit status of its final command, so an earlier failure can be hidden by a later success. `set -o pipefail` makes a script’s pipeline fail when any stage fails, which is important for trustworthy automation.',
      study: 'Build a three-stage pipeline one command at a time and save sample output from every boundary. After each stage works independently, combine them, enable `pipefail`, and deliberately break the first command to confirm that failure is detected.',
      apply: 'Inside an authorized reversing challenge, extract printable strings from a binary, preserve the complete strings output with `tee`, and display only lines containing the flag prefix. Explain what each stage receives, produces, and could fail to find.'
    },
    'cat-less-head-tail-wc-and-following-logs': {
      subtitle: 'Choose a reading tool based on file size, whether the data is still changing, and the question you need to answer. This avoids flooding the terminal or drawing a conclusion from an unrepresentative sample.',
      key: [['cat', '`cat` writes complete file contents to stdout, making it useful for small text files and for feeding another command. It is a poor interactive viewer for a huge file because it can flood the terminal without navigation controls.'], ['less', '`less` is an interactive pager that lets you move, search, and quit without printing an entire large file at once. It is a good first viewer when you need to explore rather than transform text.'], ['wc', '`wc` counts lines, words, bytes, or characters in its input. Counts provide scale and a simple way to measure how much a filter reduced a challenge dataset.']],
      good: '`head` and `tail` quickly sample the beginning or end of a file, while `tail -f` continues showing new appended lines until you stop it with Ctrl-C. A sample is a clue, not proof that the unseen middle contains nothing important.',
      study: 'Compare the same small, large, and growing test files with `cat`, `less`, `head`, `tail`, and `tail -f`. For each tool, name the question it answers, then use `wc -l` to check whether your sample represents the whole dataset.',
      apply: 'An authorized log-analysis challenge provides millions of authentication records and continues appending simulated events. Inspect the format safely, follow new failures, filter only relevant lines, and count the result without opening the entire file in an editor.'
    },
    'grep-and-regular-expression-basics': {
      subtitle: 'Search text with either exact strings or deliberately scoped patterns, and know which mode you selected. Clear search boundaries help you find evidence without being misled by shell expansion or an overly broad regex.',
      key: [['grep', '`grep` reads text and prints the lines that match a supplied pattern. Options can add filenames, line numbers, case handling, context, or recursion so the output retains enough evidence to locate each match.'], ['Regular expression', 'A regular expression is a compact language for describing sets of text strings. Its metacharacters are interpreted by `grep`, so the pattern is normally quoted to prevent Bash from changing it first.'], ['Recursive search', 'A recursive search follows a directory tree and applies the match to files below the chosen root. The starting directory defines the scope, so keep it limited to the extracted challenge workspace.']],
      good: 'Use `grep -F` when the target should be treated literally, especially for punctuation such as braces. Move to regular expressions only when you genuinely need a pattern, and quote the pattern so Bash passes it unchanged.',
      study: 'Begin with a literal search, then add filenames, line numbers, case rules, and a narrow recursive root. Write a regular expression only after the literal version cannot express the question, and test it against both matching and nonmatching examples.',
      apply: 'A directory of authorized solve logs may contain flags shaped like `picoCTF{...}`. Search only that workspace, report filenames and line numbers, treat the prefix literally, and inspect each match in context before deciding it is a valid flag.'
    },
    'cut-sort-uniq-tr-sed-and-awk': {
      subtitle: 'Turn structured text into a useful summary through small transformations whose inputs and outputs you can inspect. Simple, testable stages are easier to trust than one dense command that hides mistakes.',
      key: [['cut', '`cut` selects delimited fields or character ranges from every input line. It works well for simple, predictable rows but does not understand complex quoting rules such as full CSV grammar.'], ['sort and uniq', '`sort` orders lines so equal values become adjacent, and `uniq` collapses or counts adjacent duplicates. They are commonly paired because unsorted duplicate values separated by other lines would otherwise be counted separately.'], ['awk', '`awk` processes records and fields with pattern-action rules. It can filter, calculate, and summarize in one readable program when a chain of simpler tools would become harder to understand.']],
      good: '`uniq` only combines adjacent equal lines, so `sort` usually comes first. If commas or other delimiters can appear inside quoted fields, replace simple splitting with a parser that understands the actual file format.',
      study: 'Test each command on three hand-written lines and state the exact input and output shape. Compose the pipeline one stage at a time, comparing intermediate results and choosing the simplest tool that clearly expresses each transformation.',
      apply: 'An authorized log challenge contains `timestamp,user,result` rows. Filter failed results and count them by user, preserve one intermediate output for checking, and explain why the approach would need a real CSV parser if fields could contain quoted commas.'
    },
    'globs-find-and-safe-search-scopes': {
      subtitle: 'Distinguish patterns expanded immediately by Bash from tests evaluated recursively by `find`. Keeping the search root and pattern explicit prevents an authorized challenge search from wandering into unrelated files.',
      key: [['Glob', 'A glob is a shell pathname pattern such as `*.txt` that Bash expands into matching paths before the command runs. The receiving command sees the expanded filenames rather than the original pattern.'], ['find', '`find` walks a directory tree from a chosen root and tests each entry by name, type, time, size, and other properties. Because `find` performs the recursion, its name pattern is normally quoted so Bash does not expand it early.'], ['Search root', 'The search root is the directory where recursive traversal begins. A narrow root makes output easier to understand and keeps the operation inside the authorized challenge workspace.']],
      good: 'A glob that matches nothing may remain as literal text depending on shell settings, so do not assume an empty-looking result means the same thing everywhere. `find` receives an expression of its own and can combine tests such as regular-file type and a quoted name pattern.',
      study: 'Create a small nested tree and compare `*.txt` with `find . -type f -name "*.txt"`. Predict which program expands each pattern, test a no-match case, and repeat from a deliberately narrow subdirectory.',
      apply: 'A picoCTF bundle hides one `flag.txt` several directories deep. Search only the extracted workspace, require a regular file with the exact name, print its path, and verify the result before reading it.'
    },
    'tar-gzip-zip-and-layered-archives': {
      subtitle: 'Separate the ideas of packaging and compression, then inspect and unpack one verified layer at a time. This keeps nested challenge archives understandable and prevents extraction from overwriting unrelated files.',
      key: [['tar archive', 'A tar archive packages multiple filesystem entries and metadata into one byte stream. Tar itself is primarily a container format, so compression may be applied as a separate layer.'], ['Compression', 'Compression is a reversible transformation that represents redundant data more compactly. A compression format changes the byte stream but does not by itself organize several files into a directory structure.'], ['Extraction directory', 'An extraction directory is a dedicated destination for unpacked content. Using one keeps derived files separate from the original archive and makes unexpected names or nested layers easier to inspect.']],
      good: '`gzip` normally compresses one byte stream, while `tar` packages files before that stream is compressed in a `.tar.gz` workflow. List archive members before extraction and watch for absolute paths or parent-directory components that could escape the intended destination.',
      study: 'For tar, gzip, and zip examples, run `file`, list members without extracting, create a fresh destination, unpack, and inventory again. Record which command removed the packaging layer and which removed compression.',
      apply: 'An authorized challenge provides `backup.tar.gz` containing a second archive. Preserve both original layers, list their members before extraction, unpack each into its own directory, and document the evidence that justified the next command.'
    },
    'file-strings-xxd-and-base64': {
      subtitle: 'Triage unfamiliar bytes by identifying structure, viewing a small hexadecimal sample, extracting printable clues, and reversing only representations supported by evidence. These tools reveal leads without requiring you to execute unknown content.',
      key: [['strings', '`strings` extracts runs of printable characters from binary data. Its output can reveal filenames, messages, or flag-shaped clues, but it does not show whether the program actually uses or trusts those bytes.'], ['xxd', '`xxd` displays bytes in hexadecimal alongside a readable view and can reverse a plain hex dump. A short header view is useful for comparing magic bytes without treating the entire binary as text.'], ['base64', 'Base64 encodes arbitrary bytes as printable text and can be reversed without a secret key. It is a transport representation, not encryption, so a Base64-looking value should be decoded only after its alphabet and context support that interpretation.']],
      good: 'A `strings` match is a lead rather than proof of execution path or authenticity, and Base64 does not protect a secret. Use `file` first, inspect only enough bytes to identify structure, and save every decoded result separately so you can retrace the chain.',
      study: 'Practice on known text, image, archive, and executable samples: identify each with `file`, inspect a short `xxd` header, search `strings`, and decode a prepared Base64 value. Before each operation, state the evidence that makes that tool appropriate.',
      apply: 'An authorized forensics artifact contains a Base64-looking block after a binary header. Extract the candidate without modifying the original, decode it into a new file, identify the result, compute a checksum, and explain why the printable block alone was not sufficient proof.'
    },
    'variables-environment-and-read': {
      subtitle: 'Store values without losing their boundaries, understand which values child processes inherit, and validate input before using it. Careful variable handling keeps scripts predictable when challenge paths contain spaces or missing data.',
      key: [['Shell variable', 'A shell variable is a name-value pair stored in the current shell. It is not automatically inherited by programs the shell starts, and its expansion should normally be quoted to preserve one argument.'], ['Environment variable', 'An environment variable is exported so child processes receive a copy when they start. It is useful for configuration, but secrets placed there may be exposed through logs, debugging tools, or other process inspection.'], ['read', '`read` is a Bash builtin that accepts input into one or more variables. The `-r` option prevents backslashes from being treated as escapes, which is usually safer for paths and challenge data.']],
      good: 'Bash assignment has no spaces around `=`, because spaces would turn the text into a command and arguments. Quote expansions, check for empty or missing values, and avoid storing credentials in the environment when a safer input channel is available.',
      study: 'Assign values containing spaces and wildcard characters, print them with quoted and unquoted expansions, export one value, and inspect it from a child shell. Use `read -r` for controlled input and validate both an acceptable and rejected path.',
      apply: 'A solve script asks for an artifact path inside an authorized workspace. Read the value safely, reject empty input and anything that is not a regular file, preserve the path as one argument, and only then run `file` or another inspection command.'
    },
    'tests-conditionals-and-case': {
      subtitle: 'Make scripts choose behavior from explicit facts about strings, numbers, files, command results, and recognizable patterns. Clear branches turn manual triage decisions into reviewable automation.',
      key: [['[[ condition ]]', '`[[ condition ]]` is Bash conditional syntax for testing strings, numbers, files, and patterns with safer parsing than the older single-bracket form. Its result is still an exit status that `if` can use.'], ['if', '`if` runs a branch according to the exit status of a command or conditional expression. A zero result selects the success branch, so many ordinary commands can be tested directly.'], ['case', '`case` compares one value against ordered shell patterns and runs the first matching branch. It is often clearer than many repeated `if` tests when one file type or command output can take several known forms.']],
      good: 'Bash does not require a separate Boolean value after `if`; it evaluates whether the condition command succeeded. Keep an explicit fallback branch so unexpected input is reported rather than silently treated as a known case.',
      study: 'Practice file tests such as `-f`, `-d`, and `-s`, along with string equality, numeric comparison, direct command status, and `case` patterns. Exercise both true and false paths and describe the exit status behind each choice.',
      apply: 'An authorized triage script reads `file` output for PNG, ELF, archive, or unknown content. Use a quoted variable and a `case` statement to select the safe inspection command, then make the fallback preserve the artifact and request manual review.'
    },
    'loops-functions-and-failure-handling': {
      subtitle: 'Repeat a verified operation across several artifacts, package that operation into a reusable function, and stop or recover when an assumption fails. Reliable automation saves competition time without hiding errors.',
      key: [['for loop', 'A `for` loop repeats commands once for each item in a list. Quote the variable when using each item so filenames with spaces remain one argument.'], ['while loop', 'A `while` loop repeats as long as its condition command returns success. The condition must eventually change or consume input, otherwise the script can continue indefinitely.'], ['Function', 'A Bash function is a named group of shell commands with positional arguments and its own exit status. It makes a verified task reusable while allowing callers to detect and handle failure.']],
      good: '`set -e` is not a complete error strategy because its behavior depends on command context. Check critical operations explicitly, use `set -u` to catch unset variables, enable `pipefail` for pipelines, and print useful diagnostics to stderr.',
      study: 'Write one function that validates a regular file and returns nonzero on failure, then call it from a loop over three disposable inputs. Confirm that quoted `"$@"` preserves argument boundaries and that a failed item produces a clear message and intended stop or continue behavior.',
      apply: 'A challenge directory contains several encoded artifacts. Build a function that validates each source, writes decoded bytes to a distinct output, records failures without overwriting originals, and returns a status the outer loop can summarize.'
    },
    'permissions-chmod-and-executable-files': {
      subtitle: 'Read the owner, group, and other permission bits before changing them, then grant only the access the task requires. This least-privilege habit reduces accidental exposure in shared challenge environments.',
      key: [['Permission triplet', 'A permission triplet shows read, write, and execute bits for the file owner, group, and all other users. Reading all three triplets explains who can inspect, modify, or invoke the path.'], ['chmod', '`chmod` changes file mode permission bits using symbolic or numeric notation. A precise symbolic change such as `u+x` is easier to review than replacing every permission with an overly broad mode.'], ['Execute permission', 'Execute permission allows a valid program or script to be invoked through its path. It does not make arbitrary data safe or executable; the file still needs an appropriate format, interpreter, and trusted content.']],
      good: '`chmod +x` may add execute permission across several user classes according to context, while `chmod u+x` explicitly changes only the owner bit. Never solve a permission problem with `777` unless every granted capability is genuinely required and understood.',
      study: 'Translate several `ls -l` permission strings into owner, group, and other capabilities. Make one disposable script owner-executable, verify the exact change, inspect the script’s contents, and contrast that narrow action with an unsafe world-writable mode.',
      apply: 'An authorized picoCTF download includes a readable `solve.sh` that lacks owner execute permission. Inspect its contents first, add only `u+x`, verify the mode with `ls -l`, run it from the current directory, and leave unrelated permission bits unchanged.'
    },
    'processes-jobs-signals-and-cleanup': {
      subtitle: 'Identify running programs, distinguish shell-managed jobs from system processes, and stop the correct target with the least disruptive signal. Clean process control keeps a failed solver from consuming time or leaving hidden work behind.',
      key: [['Process', 'A process is a running instance of a program with its own identifier, state, resources, and relationships to other processes. Commands such as `ps` help you confirm which program a PID actually represents before signaling it.'], ['Job', 'A job is a command or pipeline tracked by the current interactive shell for job control. `jobs`, `fg`, and `bg` operate on this shell-local view, which is narrower than the full system process list.'], ['Signal', 'A signal is an asynchronous notification asking a process to react, stop, continue, or terminate. SIGTERM requests a graceful shutdown, while SIGKILL forces termination without giving the process cleanup time.']],
      good: '`kill` sends a signal rather than automatically using maximum force. Start with the default TERM signal, verify whether the process ended, and reserve KILL for a process that cannot respond or clean up normally.',
      study: 'Start a disposable `sleep` in the background, compare its job number with its PID, inspect it using `jobs` and `ps`, and stop it with SIGTERM. Verify the result and repeat only in your own shell so no unrelated process is targeted.',
      apply: 'During an authorized CTF, a decoder accidentally enters an infinite loop. Identify the exact process and any children, request a graceful termination, confirm that all challenge-related work ended, and preserve logs that explain the failure before restarting.'
    },
    'ssh-scp-curl-and-netcat': {
      subtitle: 'Match the client to the authorized challenge service: a remote shell, SSH-based file transfer, HTTP exchange, or simple TCP stream. Exact hosts, ports, protocols, and destinations keep the interaction inside scope.',
      key: [['ssh', '`ssh` provides an authenticated, encrypted remote shell and command channel. A connection normally needs a user, host, and sometimes a nonstandard port supplied by the challenge.'], ['scp', '`scp` transfers files using SSH authentication and transport. Carefully inspect the direction and destination path because a misplaced colon or path can copy in the opposite direction or overwrite a local file.'], ['netcat', '`netcat` is a minimal client or listener for raw TCP or UDP streams. In picoCTF it is useful for line-based services provided by a challenge, but it does not automatically add SSH authentication or HTTP structure.']],
      good: 'Copy the exact host, user, port, and protocol from the challenge prompt and verify them before connecting. Permission applies only to that endpoint and activity; it does not extend to similar hosts, public systems, or unrelated services.',
      study: 'Practice only against CyLab Academy or another system you are authorized to use. Identify the endpoint fields, inspect each client’s help, save non-sensitive output, distinguish connection errors from protocol errors, and close every session cleanly.',
      apply: 'A picoCTF prompt provides an SSH shell on a nonstandard port, a downloadable artifact, and a separate line-based TCP puzzle. Choose `ssh`, `scp`, and `nc` for their matching roles, write the exact scoped endpoints, and explain why substituting one client would fail.'
    },
    'artifact-triage-checklist': {
      subtitle: 'Use a consistent first-minute workflow to preserve an unfamiliar artifact, establish its identity, and choose the next tool from evidence rather than its name. A checklist makes fast competition work repeatable under pressure.',
      key: [['Triage', 'Triage is a rapid initial assessment that gathers enough evidence to choose the next useful action. It favors safe, broad observations before specialized parsing or execution.'], ['Checksum', 'A checksum is a digest computed from artifact bytes so later copies or transformations can be compared with the recorded original. It detects change but does not by itself prove who created the file or that the content is trustworthy.'], ['Workspace', 'A workspace is a dedicated directory holding an original copy, notes, derived files, and tool output for one challenge. Clear separation prevents accidental overwrites and lets a teammate reproduce the analysis.']],
      good: 'A strong first pass confirms location, inventories entries, hashes the original, checks metadata and type, views a short hexadecimal header, and extracts strings when appropriate. Do not execute an unknown artifact merely because a filename or challenge hint makes it look familiar.',
      study: 'Apply the same checklist to known text, image, archive, and executable samples. For every command, state the question it answers, the limitation of its output, and which observation would justify the next specialized tool.',
      apply: 'An authorized challenge download has no useful extension. Preserve it in a named workspace, record its checksum, inventory and identify it without execution, then choose and justify the next parser from observed content rather than guesswork.'
    },
    'layered-decoding-and-evidence-pipelines': {
      subtitle: 'Reverse one evidenced representation or container layer at a time, save the intermediate result, and verify its structure before continuing. This makes a complex decoding chain explainable and easy to debug.',
      key: [['Decode chain', 'A decode chain is an ordered sequence of inverse transformations used to recover underlying data. Each stage should be justified by evidence about the current layer rather than by trying random decoders.'], ['Intermediate artifact', 'An intermediate artifact is the saved output from one stage of analysis. Naming, hashing, and identifying it shows exactly where a wrong assumption or corrupted result entered the workflow.'], ['Validation', 'Validation checks whether an output has the structure, size, signature, or readable form expected before the next step. It turns a transformation from “the command ran” into evidence that the result is plausible.']],
      good: 'Do not begin with a long pipeline of guessed decoders because one early failure can make every later output meaningless. Keep stages separate until their formats and failure behavior are understood, then combine them only if the compact workflow remains testable.',
      study: 'Work prepared examples that alternate Base64, hex, compression, and archives. At every layer, record the observed clue, chosen inverse operation, output filename, checksum, `file` result, and reason the next operation is appropriate.',
      apply: 'A challenge text file decodes to gzip bytes that contain a tar archive. Build an authorized staged workflow that names and hashes every layer, validates each result before continuing, lists the archive before extraction, and can be reproduced by a teammate.'
    },
    'reusable-solve-scripts-notes-and-safe-competition-habits': {
      subtitle: 'Combine safe terminal habits into a solve workflow that can be rerun, audited, and handed to a teammate. Reproducibility turns a one-time flag discovery into evidence that the method actually works.',
      key: [['Strict mode', 'Strict mode is a common Bash setup using options such as `-u` and `pipefail` to expose missing values and hidden pipeline failures. It improves visibility but does not replace explicit validation and deliberate error handling.'], ['Idempotent step', 'An idempotent step can be repeated without producing a different, duplicated, or damaged state. Designing outputs and temporary work carefully makes reruns safer when a competition script stops halfway through.'], ['Handoff note', 'A handoff note records artifact identities, commands, observations, hypotheses, results, and current blockers for another solver. It provides enough context to continue without repeating every experiment or trusting an unexplained final flag.']],
      good: 'A solve script should never contain live credentials, contact unrelated systems, or assume every downloaded file is safe. Parameterize challenge-specific values, validate all inputs, keep temporary work scoped, and document the exact authorized environment.',
      study: 'Turn one completed lab into a script with usage text, quoted arguments, a controlled workspace, checked commands, and predictable outputs. Rerun it from a clean state, deliberately supply invalid input, and write a short README that reproduces the successful path.',
      apply: 'A teammate joins an authorized picoCTF event after your analysis is underway. Give them one safe command that reproduces the current result plus a handoff note containing the original hash, important intermediate outputs, decisions already tested, and the unresolved next question.'
    }
  };
  const lesson = (slug, title, subtitle, key, good, study, apply, source, checks, code) => ({
    slug, title, subtitle, key, good, study, apply, source, practice, checks, code, ...(expandedLessonCopy[slug] || {})
  });
  const units = [
    {
      title: 'The Shell Mental Model and Safe Habits',
      synthesis: q('What does Bash do after parsing a command line?', 'Performs expansions and redirections, then runs the selected command with arguments.', 'Treats the whole line as one filename.', 'Automatically grants administrator access.', 'The shell parses syntax, expands values, sets streams, and launches commands.'),
      lessons: [
        lesson('shell-prompts-commands-arguments-and-exit-status', 'Shell Prompts, Commands, Arguments, and Exit Status', 'Understand what Bash reads, what program it runs, and how success is reported.', [['Shell', 'A program that reads command language and starts other programs.'], ['Argument', 'A value passed to a command; the command decides what that value means.'], ['Exit status', 'An integer returned by a command, where zero conventionally means success and nonzero means failure.']], 'The prompt is interface text, not part of the command. In examples, type what follows $, not the $ itself.', 'Run a harmless command with several arguments, then inspect $? immediately. Compare a successful lookup with one that fails and explain the status difference.', 'A solve script continues after a decoder fails and submits an empty flag. Use exit status to stop the workflow at the first failed step.', manual, [q('What is Bash?', 'A shell that parses commands and starts programs.', 'A file-compression format.', 'A network protocol.', 'Bash is a command interpreter and scripting language.'), q('What exit status convention means success?', '0', '1', '255 only', 'Unix commands conventionally return zero on success.'), q('Who decides what an argument means?', 'The command receiving it.', 'The prompt theme.', 'The current filename extension.', 'Bash separates arguments; the invoked program interprets them.')], 'printf "%s\\n" "hello"\nprintf "status=%s\\n" "$?"'),
        lesson('quoting-expansion-and-command-boundaries', 'Quoting, Expansion, and Command Boundaries', 'Control when text is literal and when Bash replaces variables, globs, or command output.', [['Expansion', 'A shell step that replaces syntax such as $name, *.txt, or $(command) before execution.'], ['Single quotes', 'Quotes that preserve every character literally until the closing quote.'], ['Double quotes', 'Quotes that preserve spacing while still allowing parameter and command substitution.']], 'Unquoted variables can split into multiple arguments and expand wildcard characters. Quote "$variable" unless splitting is specifically intended.', 'Predict the exact argument list before running examples with spaces, *, single quotes, double quotes, and command substitution. Verify with printf brackets.', 'A downloaded artifact is named challenge files/flag one.txt. Build a command that reads the exact path without treating spaces as separators.', manual, [q('Which quotes prevent variable expansion?', 'Single quotes.', 'Double quotes.', 'No quotes only.', 'Single quotes preserve enclosed characters literally.'), q('Why use "$file"?', 'It keeps the variable value as one argument and prevents glob expansion.', 'It converts the file to Base64.', 'It makes every command succeed.', 'Double quotes protect boundaries while expanding the variable.'), q('What does $(command) do?', 'Substitutes the command’s standard output.', 'Comments out the command.', 'Runs as administrator.', 'Command substitution places captured output into the surrounding command line.')], 'file="challenge files/flag one.txt"\ncat "$file"\nprintf "<%s>\\n" "$file"'),
        lesson('help-man-type-which-and-history', 'Help, man, type, which, and History', 'Make the terminal self-documenting before searching for a copied command online.', [['Builtin', 'A command implemented by the shell itself rather than a separate executable.'], ['man page', 'A structured local reference describing a command, options, files, and behavior.'], ['type', 'A Bash builtin that explains how a command name will be resolved.']], 'Use help for Bash builtins and man for most external commands. command --help is often the fastest option summary.', 'For every new command, locate its help, find one option, run a harmless example, and explain the output. Use history carefully because commands may contain secrets.', 'During a competition, a teammate remembers a command name but not its options. Find its local documentation and verify whether it is a builtin, alias, or executable.', manual, [q('Which command explains how Bash resolves a name?', 'type', 'base64', 'chmod', 'type reports aliases, builtins, functions, and executable paths.'), q('Where are Bash builtin details commonly found?', 'help command', 'file command', 'strings command', 'help is itself a Bash builtin for builtin documentation.'), q('Why can shell history be sensitive?', 'Commands may contain tokens, passwords, or private paths.', 'History encrypts every command.', 'It changes exit statuses.', 'Typed secrets can be saved in history files.')], 'type cd\nhelp cd\nman grep\ngrep --help')
      ]
    },
    {
      title: 'Filesystem Navigation and Safe File Operations',
      synthesis: q('What is the safest way to confirm a destructive file command?', 'Resolve the current directory and exact targets with pwd and ls before running it.', 'Add more wildcards.', 'Run it from an unknown directory.', 'Visible, explicit targets reduce accidental data loss.'),
      lessons: [
        lesson('pwd-cd-and-paths', 'pwd, cd, and Paths', 'Know exactly where you are and how Bash resolves a file location.', [['Working directory', 'The directory used as the starting point for relative paths.'], ['Absolute path', 'A path beginning at the filesystem root and independent of the working directory.'], ['Relative path', 'A path interpreted from the current working directory.']], '. means the current directory and .. means its parent. ~ expands to the current user’s home directory.', 'Draw a small directory tree and predict the result of cd plus relative paths before checking with pwd. Practice returning safely with cd -.', 'A challenge bundle contains nested folders and duplicate filenames. Navigate to the correct artifact and prove its absolute location before analyzing it.', manual, [q('What does pwd print?', 'The current working directory.', 'Every running process.', 'The file type.', 'pwd means print working directory.'), q('What does .. name in a path?', 'The parent directory.', 'The current directory.', 'The home directory.', 'Two dots refer to the parent.'), q('What makes a path absolute?', 'It begins from the filesystem root.', 'It contains a wildcard.', 'It has exactly one component.', 'Absolute paths do not depend on the current working directory.')], 'pwd\ncd challenge/artifacts\npwd\ncd -'),
        lesson('ls-stat-file-and-hidden-entries', 'ls, stat, file, and Hidden Entries', 'Inventory names, permissions, times, sizes, and actual file types.', [['Hidden entry', 'A Unix filename whose first character is a dot.'], ['stat', 'A command reporting detailed filesystem metadata for a path.'], ['file', 'A command that inspects content signatures and structure to estimate a file type.']], 'ls -a reveals dotfiles; ls -l shows a long listing. Neither proves content type, so use file for unfamiliar artifacts.', 'Given a directory, inventory it with ls -la, compare sizes and timestamps with stat, then run file before choosing a parser.', 'A directory appears empty in a normal listing. Reveal hidden entries, inspect their metadata, and identify which one is actually an archive.', 'https://picoctf.org/learning_guides/Book-1-General-Skills.pdf', [q('Which option makes ls include hidden names?', '-a', '-d', '-r only', 'Dotfiles are omitted unless all entries are requested.'), q('What does file inspect?', 'Content signatures and structure.', 'Only the filename extension.', 'The shell history.', 'file does not need to trust the extension.'), q('What does stat provide?', 'Detailed filesystem metadata.', 'Automatic decryption.', 'A network connection.', 'stat reports size, permissions, times, and identifiers.')], 'ls -la\nstat mystery.bin\nfile mystery.bin'),
        lesson('mkdir-touch-cp-mv-and-safe-removal', 'mkdir, touch, cp, mv, and Safe Removal', 'Create and organize a working copy without damaging the original evidence.', [['mkdir', 'Creates a directory.'], ['cp', 'Copies files or directories, leaving the source in place.'], ['mv', 'Moves or renames a path.']], 'rm normally deletes without a recycle bin. Avoid broad wildcards, confirm pwd and targets, and preserve challenge originals.', 'Create a temporary workspace, copy an artifact into it, rename only the copy, and list both source and destination. Practice removal only on disposable test files.', 'You receive evidence.zip. Build a workspace that preserves the original, records a checksum, and performs all extraction on a copy.', manual, [q('Which command preserves the source while creating another file?', 'cp', 'mv', 'rm', 'cp creates a copy.'), q('What can mv do within one filesystem?', 'Move or rename a path.', 'Print file contents.', 'Decode Base64.', 'A new destination name effectively renames the entry.'), q('What should happen before rm with a wildcard?', 'Confirm the working directory and expanded targets.', 'Add sudo automatically.', 'Hide the listing.', 'rm is difficult to undo, so targets must be explicit and verified.')], 'mkdir -p work\ncp evidence.zip work/evidence-copy.zip\nls -l evidence.zip work/evidence-copy.zip')
      ]
    },
    {
      title: 'Streams, Redirection, and Pipelines',
      synthesis: q('What makes a pipeline composable?', 'Each command reads a stream, performs one clear transformation, and writes a stream for the next command.', 'Every command edits the same file.', 'Pipes always suppress errors.', 'Stream-oriented tools can be chained without temporary files.'),
      lessons: [
        lesson('stdin-stdout-stderr-and-file-descriptors', 'stdin, stdout, stderr, and File Descriptors', 'Track ordinary input, ordinary output, and diagnostic output as separate streams.', [['stdin', 'Standard input, file descriptor 0, from which a command normally reads.'], ['stdout', 'Standard output, file descriptor 1, for normal results.'], ['stderr', 'Standard error, file descriptor 2, for diagnostics and errors.']], 'Separating stdout and stderr lets a pipeline process valid data without mixing in warning text.', 'Run a command that produces both output and an error. Redirect each stream separately and inspect the resulting files.', 'A decoder prints flags to stdout and malformed-record warnings to stderr. Save the valid results while preserving warnings for review.', manual, [q('Which file descriptor is stdout?', '1', '0', '2', 'Standard output is descriptor 1.'), q('Why is stderr separate?', 'Diagnostics can be handled without contaminating normal output.', 'It is always encrypted.', 'It replaces exit status.', 'Separate streams support clean data pipelines and visible errors.'), q('Where does a command normally read input?', 'stdin', 'stderr', 'the process list', 'Standard input is descriptor 0.')], 'tool input.bin > results.txt 2> warnings.txt'),
        lesson('redirecting-input-output-and-errors', 'Redirecting Input, Output, and Errors', 'Connect streams to files deliberately and understand when data is replaced or appended.', [['>', 'Redirects stdout to a file and truncates that file first.'], ['>>', 'Redirects stdout to the end of a file.'], ['2>', 'Redirects stderr to a file.']], 'Redirection is set up by the shell before the command runs. A mistaken > can erase an existing file even if the command later fails.', 'Practice with disposable files: create with >, append with >>, read via <, and split stdout from stderr. Check sizes after each step.', 'A competition script must add one result per challenge without erasing earlier entries. Choose the correct redirection and keep errors in a separate log.', manual, [q('Which operator appends stdout?', '>>', '>', '<', 'Double greater-than appends.'), q('What does > do to an existing destination?', 'Truncates it before writing.', 'Always appends.', 'Makes it executable.', 'Standard output redirection with > replaces prior content.'), q('How is stderr redirected alone?', '2>', '0>', '>> only', 'stderr uses file descriptor 2.')], 'printf "first\\n" > notes.txt\nprintf "second\\n" >> notes.txt\ncommand 2> errors.log'),
        lesson('pipes-tee-and-command-substitution', 'Pipes, tee, and Command Substitution', 'Chain focused tools while keeping useful intermediate output visible.', [['Pipe', 'The | operator connects one command’s stdout to the next command’s stdin.'], ['tee', 'Copies stdin to stdout and one or more files.'], ['Command substitution', 'The $(command) form captures command output for use in another command line.']], 'A pipeline’s final status normally reflects the last command. set -o pipefail makes a failure earlier in the pipeline visible to scripts.', 'Build pipelines one stage at a time, inspect sample output, then combine. Enable pipefail in scripts where every stage must succeed.', 'You must extract printable text from a binary, save all strings, and display only lines containing the flag prefix. Design a pipeline with tee.', manual, [q('What does | connect?', 'stdout of the left command to stdin of the right command.', 'stderr to a password.', 'Two directories permanently.', 'Pipes transport stream data between processes.'), q('What does tee provide?', 'A copy to a file while continuing the pipeline.', 'Automatic encryption.', 'A recursive directory search.', 'tee splits one input stream to both file and stdout.'), q('Why use pipefail in a script?', 'To detect failure in any pipeline stage.', 'To make every command return zero.', 'To disable stderr.', 'Without it, an early failure may be hidden by a successful final command.')], 'set -o pipefail\nstrings challenge | tee all-strings.txt | grep "picoCTF"')
      ]
    },
    {
      title: 'Reading, Searching, and Transforming Text',
      synthesis: q('What is the best pipeline design for a large log?', 'Filter early, keep only needed fields, then sort or summarize.', 'Print the entire file after every stage.', 'Use one huge regular expression before inspecting data.', 'Early reduction makes the pipeline easier to reason about and faster.'),
      lessons: [
        lesson('cat-less-head-tail-wc-and-following-logs', 'cat, less, head, tail, wc, and Following Logs', 'Choose a viewer that matches the file size and the question.', [['cat', 'Writes file contents to stdout; useful for small files and pipelines.'], ['less', 'An interactive pager for navigating text without loading it all into the terminal at once.'], ['wc', 'Counts lines, words, and bytes or characters.']], 'tail -f follows appended log data; stop it with Ctrl-C. head and tail are fast sampling tools, not proof that the middle is irrelevant.', 'For small, medium, and growing files, choose cat, less, head, tail, or tail -f and explain why. Count before assuming a sample is representative.', 'An authentication log is millions of lines and still growing. Inspect its first records, follow new failures, and count the filtered result without opening an editor.', 'https://picoctf.org/learning_guides/Book-1-General-Skills.pdf', [q('Which tool is best for interactively paging through a large text file?', 'less', 'touch', 'chmod', 'less supports navigation and search without flooding the terminal.'), q('What does wc -l count?', 'Lines', 'Directories only', 'Running processes', 'The -l option counts newline-delimited lines.'), q('What does tail -f do?', 'Displays new lines as a file grows.', 'Deletes the file tail.', 'Finds file types.', 'Follow mode is useful for live logs.')], 'head -n 20 auth.log\ntail -f auth.log\ngrep failed auth.log | wc -l'),
        lesson('grep-and-regular-expression-basics', 'grep and Regular-Expression Basics', 'Search text by literal words or carefully scoped patterns.', [['grep', 'A command that prints lines matching a pattern.'], ['Regular expression', 'A compact language describing text patterns.'], ['Recursive search', 'Searching matching files through a directory tree.']], 'Quote regex patterns so Bash does not expand metacharacters first. Use grep -F when the target should be treated literally.', 'Start with a literal search, add line numbers and case rules, then expand to a regex only when the question requires a pattern.', 'A directory of solve logs may contain flags in the form picoCTF{...}. Search recursively, include filenames and line numbers, and avoid treating braces as shell syntax.', 'https://picoctf.org/learning_guides/Book-1-General-Skills.pdf', [q('What does grep normally output?', 'Lines matching the pattern.', 'Only filenames regardless of match.', 'Decoded archives.', 'grep filters text by matching lines.'), q('Why quote a regex?', 'To prevent the shell from interpreting its special characters first.', 'To encrypt it.', 'To make it recursive.', 'The regex should reach grep as one unchanged argument.'), q('When is grep -F useful?', 'When the pattern should be matched literally.', 'When changing permissions.', 'When sorting numerically.', 'Fixed-string mode disables regex interpretation.')], 'grep -RFn "picoCTF{" solve-logs/'),
        lesson('cut-sort-uniq-tr-sed-and-awk', 'cut, sort, uniq, tr, sed, and awk', 'Turn rows into useful summaries with small, testable transformations.', [['cut', 'Selects delimited fields or character ranges from each input line.'], ['sort and uniq', 'Orders lines and then collapses or counts adjacent duplicates.'], ['awk', 'Processes records and fields with pattern-action rules.']], 'uniq only combines adjacent equal lines, so sort usually comes first. CSV quoting can exceed simple delimiter tools; use a real parser for complex CSV.', 'Test each tool on three lines, state its input and output shape, then compose. Prefer the simplest tool that expresses the transformation clearly.', 'A log has timestamp,user,result fields. Count failed logins per user using a pipeline, then explain the limitation if fields can contain commas.', manual, [q('Why is sort commonly used before uniq -c?', 'uniq counts adjacent duplicates, and sort groups equal lines.', 'sort decrypts the input.', 'uniq can read only sorted files.', 'Grouping equal lines makes their counts meaningful.'), q('What does cut select?', 'Fields or character ranges from each line.', 'File permissions.', 'Network packets.', 'cut performs simple column extraction.'), q('When should a real CSV parser replace cut?', 'When quoting, embedded delimiters, or newlines are possible.', 'Whenever the file has one column.', 'Only for binary files.', 'CSV grammar is more complex than splitting every comma.')], 'cut -d, -f2,3 events.csv | sort | uniq -c\nawk -F, "$3 == \"failed\" { count[$2]++ } END { for (u in count) print u, count[u] }" events.csv')
      ]
    },
    {
      title: 'Finding Files, Archives, and Binary Clues',
      synthesis: q('What should happen before extracting an unfamiliar archive?', 'List its contents and extract into a dedicated directory.', 'Run every contained executable.', 'Rename it to .txt.', 'Previewing paths and isolating extraction reduce surprises.'),
      lessons: [
        lesson('globs-find-and-safe-search-scopes', 'Globs, find, and Safe Search Scopes', 'Know whether Bash or find is selecting paths and keep the search boundary explicit.', [['Glob', 'A shell pathname pattern such as *.txt expanded before the command runs.'], ['find', 'A command that walks a directory tree and tests entries by name, type, time, size, and more.'], ['Search root', 'The directory where a recursive search begins.']], 'A glob that matches nothing may remain literal depending on shell settings. find receives its own expression and performs the recursion itself.', 'Create a small tree and compare *.txt with find . -name "*.txt". Quote the find pattern so Bash does not expand it early.', 'A challenge bundle hides one file named flag.txt several directories deep. Search only the extracted workspace and print the exact matching path.', 'https://picoctf.org/learning_guides/Book-1-General-Skills.pdf', [q('Who expands *.txt in a normal command?', 'The shell before launching the command.', 'The file command.', 'The kernel after output.', 'Globbing is a shell expansion.'), q('Why quote "*.txt" in find?', 'So find, not Bash, receives and evaluates the pattern.', 'To turn files into strings.', 'To make the search global.', 'Unquoted patterns may expand in the current directory too early.'), q('What is a search root?', 'The directory where recursive traversal begins.', 'The regular-expression delimiter.', 'A user password.', 'Explicit roots keep searches scoped and efficient.')], 'find ./workspace -type f -name "*.txt" -print'),
        lesson('tar-gzip-zip-and-layered-archives', 'tar, gzip, zip, and Layered Archives', 'Distinguish packaging from compression and unpack one verified layer at a time.', [['tar archive', 'A stream that packages multiple filesystem entries and metadata.'], ['Compression', 'A reversible transformation reducing data size by exploiting redundancy.'], ['Extraction directory', 'A dedicated destination that contains unpacked files away from the original.']], 'gzip normally compresses one byte stream; tar often packages files before gzip compresses the archive. A .tar.gz name reflects both layers.', 'Run file, list without extraction, create a destination, extract, and inventory again. Repeat for nested layers while preserving each original.', 'A challenge gives backup.tar.gz containing another archive. Document the type and members of each layer without overwriting either artifact.', manual, [q('What is tar primarily for?', 'Packaging files and metadata into one archive stream.', 'Encrypting network sessions.', 'Searching regex patterns.', 'tar is an archiver; compression is a separate operation.'), q('What does .tar.gz usually mean?', 'A tar archive compressed with gzip.', 'A PNG renamed twice.', 'An SSH private key.', 'The suffix names the packaging and compression layers.'), q('Why extract into a dedicated directory?', 'To contain paths and keep the workspace understandable.', 'To make every file executable.', 'To remove hashes.', 'Isolation protects surrounding files and preserves structure.')], 'tar -tzf bundle.tar.gz\nmkdir extracted\ntar -xzf bundle.tar.gz -C extracted'),
        lesson('file-strings-xxd-and-base64', 'file, strings, xxd, and Base64', 'Triage unfamiliar bytes, inspect printable clues, and reverse common representations.', [['strings', 'Extracts runs of printable characters from binary data.'], ['xxd', 'Displays bytes as hexadecimal and can reverse a plain hex dump.'], ['base64', 'Encodes bytes as printable text and decodes them with the inverse option.']], 'A strings match is a clue, not proof of execution path or authenticity. Base64 is representation, not encryption.', 'Use file first, inspect a short hex header, search strings, then decode only when evidence identifies the representation. Save each result separately.', 'An unknown artifact contains a Base64-looking printable block after a binary header. Plan how to extract, decode, identify, and hash the next layer.', primer, [q('What does strings extract?', 'Runs of printable characters from binary data.', 'Every instruction’s meaning.', 'Only encrypted keys.', 'Printable sequences can reveal messages, paths, and symbols.'), q('Which command can reverse a plain hex dump?', 'xxd -r', 'pwd', 'chmod', 'xxd supports forward and reverse conversion.'), q('Does Base64 provide secrecy?', 'No; it is reversible without a key.', 'Yes, if it ends in =.', 'Only on Linux.', 'Encoding does not enforce access control.')], 'file challenge.bin\nxxd -l 32 challenge.bin\nstrings -n 6 challenge.bin | grep "picoCTF"\nbase64 -d encoded.txt')
      ]
    },
    {
      title: 'Bash Variables, Decisions, Loops, and Functions',
      synthesis: q('What makes a Bash solve script reliable?', 'Quoted variables, checked exit statuses, explicit inputs, and small testable steps.', 'Ignoring every error.', 'Using the shortest possible variable names.', 'Reliability comes from controlled boundaries and visible failures.'),
      lessons: [
        lesson('variables-environment-and-read', 'Variables, Environment, and read', 'Store values safely and understand which variables child processes receive.', [['Shell variable', 'A name-value pair stored in the current shell.'], ['Environment variable', 'A variable exported so child processes receive it.'], ['read', 'A Bash builtin that reads input into one or more variables.']], 'Assignment has no spaces around =. Quote expansions and avoid putting secrets in environment variables when process inspection or logs could expose them.', 'Assign values with spaces, print them safely, export one value, inspect it from a child shell, and read controlled input with a prompt.', 'A script accepts an artifact path from the user. Validate that the input is nonempty and names a regular file before analysis.', manual, [q('How is a Bash variable assigned?', 'name=value', 'name = value', '$name=value', 'Spaces around = change the tokens into a command invocation.'), q('What does export do?', 'Makes a variable available to child processes.', 'Writes it to a file automatically.', 'Encrypts the value.', 'Export adds the variable to the process environment.'), q('Why quote "$path"?', 'To preserve the path as one argument.', 'To make it absolute.', 'To grant permission.', 'Quoting prevents word splitting and wildcard expansion.')], 'read -r -p "Artifact path: " path\nif [[ -f "$path" ]]; then file "$path"; fi'),
        lesson('tests-conditionals-and-case', 'Tests, Conditionals, and case', 'Choose behavior from explicit facts about strings, numbers, files, and patterns.', [['[[ condition ]]', 'Bash conditional syntax with safer string and pattern behavior than the older single-bracket form.'], ['if', 'Runs a branch according to a command’s exit status.'], ['case', 'Matches one value against ordered shell patterns.']], 'In Bash, if tests a command status, not a Boolean type. Many commands can be used directly as conditions.', 'Practice -f, -d, -s, string equality, numeric comparison, and case patterns. For each, test both the true and false path.', 'A triage script should run different inspection commands for PNG, ELF, and archive files based on file output. Design a case statement and an unknown fallback.', manual, [q('What does if use to choose a branch?', 'The exit status of its condition command.', 'Only the text true or false.', 'The file extension automatically.', 'Zero status selects the success branch.'), q('Which test checks for a regular file?', '-f', '-d', '-z only', '-f is true for an existing regular file.'), q('When is case useful?', 'Matching one value against several patterns.', 'Changing file ownership.', 'Following a log.', 'case expresses readable multi-pattern branching.')], 'kind=$(file -b "$path")\ncase "$kind" in\n  *PNG*) echo image ;;\n  *ELF*) echo executable ;;\n  *) echo unknown ;;\nesac'),
        lesson('loops-functions-and-failure-handling', 'Loops, Functions, and Failure Handling', 'Repeat one verified operation and stop when its assumptions fail.', [['for loop', 'Repeats commands for each item in a list.'], ['while loop', 'Repeats while its condition command succeeds.'], ['Function', 'A named group of shell commands with positional arguments and an exit status.']], 'set -e is not a complete error strategy. Check critical commands explicitly, use set -u for unset variables, and pipefail for pipelines.', 'Write one function that validates a file, loop over three disposable inputs, and make a failed validation stop with a useful stderr message.', 'A directory contains many encoded challenge artifacts. Build a function that checks each file, decodes to a separate output, and records failures without overwriting inputs.', manual, [q('What does "$@" represent inside a function or script?', 'All positional arguments while preserving their boundaries when quoted.', 'Only the first argument.', 'Every environment variable.', 'Quoted "$@" passes arguments individually and safely.'), q('What does set -u help detect?', 'Use of unset variables.', 'Open network ports.', 'Duplicate lines.', 'Unset-variable errors often reveal misspellings and missing inputs.'), q('Why return a nonzero status from a failed function?', 'Callers can detect and handle the failure.', 'It makes the output longer.', 'It grants execute permission.', 'Exit status is the shell’s composable success signal.')], 'set -u -o pipefail\ninspect() {\n  [[ -f "$1" ]] || { echo "missing: $1" >&2; return 1; }\n  file "$1"\n}\nfor artifact in "$@"; do inspect "$artifact" || exit 1; done')
      ]
    },
    {
      title: 'Permissions, Processes, and Remote Tools',
      synthesis: q('What principle connects file permissions and process control?', 'Act with only the access needed and target the exact object or process intended.', 'Every command should run as root.', 'Permissions replace authentication.', 'Least privilege and precise targets reduce mistakes and compromise impact.'),
      lessons: [
        lesson('permissions-chmod-and-executable-files', 'Permissions, chmod, and Executable Files', 'Read owner/group/other permissions and change only the bits the task requires.', [['Permission triplet', 'Read, write, and execute bits shown for owner, group, and others.'], ['chmod', 'Changes file mode permissions.'], ['Execute permission', 'Allows a file to be invoked as a program when its format and interpreter are valid.']], 'chmod +x adds execute permission broadly according to the current umask context; chmod u+x is explicit about the owner only.', 'Translate symbolic permissions to meaning, make one script owner-executable, and verify with ls -l. Avoid granting world-write access.', 'A downloaded solve.sh is readable but not executable. Grant only the owner execute permission, inspect the script, then run it from the current directory.', manual, [q('What does chmod u+x do?', 'Adds execute permission for the owner.', 'Makes every user an administrator.', 'Deletes write permission from all users.', 'u means owner and +x adds its execute bit.'), q('Why might ./solve.sh be needed?', 'The current directory is normally not searched through PATH.', 'The file is encrypted.', 'Bash cannot run scripts.', './ names the file path explicitly.'), q('What does least privilege suggest?', 'Grant only the permissions actually needed.', 'Use mode 777 for convenience.', 'Run every tool as root.', 'Narrow access reduces the damage of mistakes or compromise.')], 'chmod u+x solve.sh\nls -l solve.sh\n./solve.sh'),
        lesson('processes-jobs-signals-and-cleanup', 'Processes, Jobs, Signals, and Cleanup', 'Observe running commands, control background work, and stop the correct process gracefully.', [['Process', 'A running instance of a program with an identifier and resources.'], ['Job', 'A pipeline tracked by the current interactive shell.'], ['Signal', 'An asynchronous notification asking a process to react, stop, continue, or terminate.']], 'kill sends a signal; it is not always immediate force. Start with the default TERM signal and reserve KILL for a process that cannot clean up.', 'Run a disposable sleep in the background, inspect jobs and ps, bring it forward or signal it, then verify it ended.', 'A decoder accidentally loops forever during a CTF. Identify its PID, send a graceful termination, and confirm no child process was left running.', manual, [q('What does & do at the end of a command?', 'Starts it as a background job.', 'Redirects stderr.', 'Makes it executable.', 'The shell returns a prompt while the job runs.'), q('What does kill normally send by default?', 'SIGTERM', 'SIGKILL only', 'stdout', 'TERM requests graceful termination.'), q('How do jobs and ps differ?', 'jobs shows work tracked by the current shell; ps reports processes.', 'They are identical aliases.', 'ps changes permissions.', 'Job control is shell-local; process inspection is system-level.')], 'sleep 300 &\njobs\nps -f\nkill "$!"'),
        lesson('ssh-scp-curl-and-netcat', 'ssh, scp, curl, and netcat', 'Connect to authorized challenge services and transfer only the data you intend.', [['ssh', 'An encrypted remote shell and command protocol.'], ['scp', 'File transfer over SSH authentication and transport.'], ['netcat', 'A minimal client or listener for raw TCP or UDP streams.']], 'Always copy the exact host and port from the challenge. A connection command is permission only for that challenge endpoint.', 'Practice against CyLab Academy: identify host, user, port, and protocol; inspect help; save output; and close the session cleanly.', 'A challenge gives an SSH service on a nonstandard port and a separate TCP puzzle. Choose ssh for the shell and nc for the line-based service.', 'https://picoctf.org/learning_guides/Book-1-General-Skills.pdf', [q('Which ssh option selects a port?', '-p', '-P only', '-l means port', 'Lowercase -p sets the SSH destination port.'), q('What does scp provide?', 'File transfer over SSH.', 'Packet capture analysis.', 'Hex decoding.', 'scp reuses SSH transport and authentication.'), q('When is nc appropriate in picoCTF?', 'For a simple authorized TCP service supplied by the challenge.', 'For editing image pixels.', 'For changing permissions.', 'Netcat exposes the raw line or byte exchange.')], 'ssh -p 2222 learner@challenge.example.invalid\nscp -P 2222 learner@challenge.example.invalid:artifact.bin .\nnc challenge.example.invalid 31337')
      ]
    },
    {
      title: 'picoCTF Terminal Workflows and Automation',
      synthesis: q('What makes a fast CTF terminal workflow trustworthy?', 'It preserves artifacts, records commands, checks failures, and makes each transformation reproducible.', 'It hides every intermediate result.', 'It runs unknown files immediately.', 'Speed comes from a reliable loop, not skipped evidence.'),
      lessons: [
        lesson('artifact-triage-checklist', 'Artifact Triage Checklist', 'Use a fixed first minute so unfamiliar files become evidence instead of guesses.', [['Triage', 'A rapid initial assessment used to choose the next useful action.'], ['Checksum', 'A digest used to compare whether artifact bytes changed.'], ['Workspace', 'A dedicated directory containing copies, notes, and derived files for one challenge.']], 'A strong first pass is pwd, ls -la, sha256sum, file, stat, a short xxd header, and strings when appropriate—without executing the artifact.', 'Practice the checklist on text, image, archive, and executable samples. For each command, state the question it answers.', 'A challenge download has no useful extension. Preserve it, inventory it, identify its type, and choose the next tool based on evidence.', primer, [q('Which command should usually precede choosing a format-specific tool?', 'file', 'chmod 777', 'rm', 'Content type guides the next parser or viewer.'), q('Why compute a checksum?', 'To recognize whether bytes change during analysis.', 'To grant permission.', 'To reveal every hidden string.', 'A recorded digest is an integrity baseline.'), q('Should an unknown binary be executed during first triage?', 'No; inspect it first and use only an isolated authorized environment if execution is needed.', 'Yes, always.', 'Only after renaming it.', 'Unknown code deserves cautious static inspection first.')], 'mkdir -p work\ncp challenge work/original\nsha256sum work/original\nfile work/original\nxxd -l 32 work/original'),
        lesson('layered-decoding-and-evidence-pipelines', 'Layered Decoding and Evidence Pipelines', 'Reverse one evidenced transformation at a time and verify each output.', [['Decode chain', 'An ordered series of inverse transformations applied to recover the underlying data.'], ['Intermediate artifact', 'The output of one stage saved so it can be identified and reproduced.'], ['Validation', 'A check that output structure matches what the next step expects.']], 'Do not blindly pipe ten decoders together. Save and identify intermediate output until the chain is understood; combine it only after validation.', 'Work examples that alternate Base64, hex, compression, and archives. At every layer, write the evidence for the next inverse operation.', 'A text file decodes to gzip bytes, which contain a tar archive. Build a staged workflow that names, identifies, and hashes each layer.', primer, [q('What should justify each decoder in a chain?', 'Evidence identifying the current representation.', 'A guess that the flag is hidden.', 'The filename color.', 'Each inverse operation should match observable structure.'), q('Why save intermediate artifacts?', 'They make the chain inspectable and reproducible.', 'They automatically decrypt the next layer.', 'They avoid all storage use.', 'Saved stages reveal where an assumption fails.'), q('When should a pipeline replace staged files?', 'After the transformations and failure behavior are understood and tested.', 'Before inspecting any input.', 'Never for repeatable work.', 'Compact pipelines are valuable after their stages are verified.')], 'base64 -d layer1.txt > layer2.bin\nfile layer2.bin\ngzip -dc layer2.bin > layer3.tar\ntar -tf layer3.tar'),
        lesson('reusable-solve-scripts-notes-and-safe-competition-habits', 'Reusable Solve Scripts, Notes, and Safe Competition Habits', 'Package the terminal habits into a repeatable workflow a teammate can audit.', [['Strict mode', 'A common Bash setup using options such as -u and pipefail to expose missing values and pipeline failures.'], ['Idempotent step', 'An operation designed so repeating it does not create a different or damaged state.'], ['Handoff note', 'A concise record of artifacts, commands, observations, hypotheses, and blockers for another solver.']], 'A solve script should not contain live credentials or target unrelated hosts. Parameterize challenge-specific values and validate inputs.', 'Turn one solved lab into a script with usage text, quoted arguments, a temporary workspace, checked commands, and a README reproducing the result.', 'A teammate joins late. Give them one command to reproduce the analysis plus a note that explains the artifact hash, outputs, and unresolved question.', manual, [q('What does a reproducible solve script need?', 'Explicit inputs, checked commands, quoted values, and documented outputs.', 'Hard-coded private credentials.', 'Unbounded destructive commands.', 'Reliable automation makes assumptions visible.'), q('Why aim for idempotent steps?', 'Rerunning the workflow should not corrupt or multiply results unexpectedly.', 'It makes every command silent.', 'It bypasses permissions.', 'Repeatability is safer when repeated work has the same effect.'), q('What belongs in a handoff note?', 'Evidence, commands, results, hypotheses, and the current blocker.', 'Only the final flag.', 'Unrelated personal data.', 'A handoff lets another solver continue without repeating the entire search.')], '#!/usr/bin/env bash\nset -u -o pipefail\n[[ $# -eq 1 && -f "$1" ]] || { echo "usage: $0 ARTIFACT" >&2; exit 2; }\nsha256sum "$1"\nfile "$1"')
      ]
    }
  ];

  const labs = [
    { title: 'Confirm the Working Directory', brief: 'You need to print the absolute path of the current directory.', artifact: '$ _', prompt: 'Enter the command.', answers: ['pwd'], hint: 'The name means print working directory.', explain: 'pwd reports the shell’s current directory.' },
    { title: 'Reveal Hidden Files', brief: 'List the current directory in long form, including dotfiles.', artifact: '$ _', prompt: 'Enter the command.', answers: ['ls -la', 'ls -al', 'ls -l -a', 'ls -a -l'], hint: 'Combine the long-listing and all-files options.', explain: 'ls -la shows metadata and entries beginning with a dot.' },
    { title: 'Read a Small Flag File', brief: 'Print the entire small text file flag.txt to stdout.', artifact: '$ _', prompt: 'Enter the command.', answers: ['cat flag.txt', 'cat ./flag.txt'], hint: 'Use the simple command that concatenates a file to stdout.', explain: 'cat is appropriate for a small text file.' },
    { title: 'Search for the Flag Prefix', brief: 'Print lines in notes.txt containing the literal text picoCTF{.', artifact: '$ _', prompt: 'Enter the command.', answers: ['grep -F "picoCTF{" notes.txt', "grep -F 'picoCTF{' notes.txt", 'grep "picoCTF{" notes.txt', "grep 'picoCTF{' notes.txt"], hint: 'Use grep; fixed-string mode avoids regex interpretation.', explain: 'grep -F treats the braces as literal characters.' },
    { title: 'Find Text Artifacts Recursively', brief: 'From the current directory, find regular files whose names end in .txt.', artifact: '$ _', prompt: 'Enter the command.', answers: ['find . -type f -name "*.txt"', "find . -type f -name '*.txt'", 'find . -name "*.txt" -type f', "find . -name '*.txt' -type f"], hint: 'Quote the wildcard so find receives it.', explain: 'find walks from . and applies both the file-type and name tests.' },
    { title: 'Identify Unknown Content', brief: 'Inspect mystery.bin without trusting its extension.', artifact: '$ _', prompt: 'Enter the command.', answers: ['file mystery.bin', 'file ./mystery.bin'], hint: 'Use the command that reads file signatures.', explain: 'file inspects content signatures and structure.' },
    { title: 'Search Printable Binary Clues', brief: 'Extract printable strings from app and show only those containing picoCTF.', artifact: '$ _', prompt: 'Enter the pipeline.', answers: ['strings app | grep picoCTF', 'strings ./app | grep picoCTF', 'strings app | grep -F picoCTF', 'strings ./app | grep -F picoCTF'], hint: 'Pipe strings output into grep.', explain: 'The pipeline narrows printable binary content to candidate flag strings.' },
    { title: 'Decode a Base64 File', brief: 'Decode encoded.txt to stdout.', artifact: '$ _', prompt: 'Enter the command.', answers: ['base64 -d encoded.txt', 'base64 --decode encoded.txt', 'base64 -d < encoded.txt', 'base64 --decode < encoded.txt'], hint: 'Use base64 with its decode option.', explain: 'Base64 decoding reverses the printable representation.' },
    { title: 'Reverse a Plain Hex Dump', brief: 'Convert the continuous plain hex in flag.hex back to bytes.', artifact: '$ _', prompt: 'Enter the command.', answers: ['xxd -r -p flag.hex', 'xxd -r -p < flag.hex', 'xxd -r -ps flag.hex'], hint: 'xxd supports reverse and plain modes.', explain: 'xxd -r -p interprets plain hexadecimal pairs as bytes.' },
    { title: 'Grant Owner Execute Permission', brief: 'Make solve.sh executable only by adding execute permission for its owner.', artifact: '-rw-r--r-- 1 learner learner 241 solve.sh', prompt: 'Enter the command.', answers: ['chmod u+x solve.sh', 'chmod u+x ./solve.sh'], hint: 'Use symbolic mode: user plus execute.', explain: 'chmod u+x changes only the owner execute bit.' },
    { title: 'Connect to a Nonstandard SSH Port', brief: 'Connect as learner to challenge.example on SSH port 2222.', artifact: '$ _', prompt: 'Enter the command.', answers: ['ssh -p 2222 learner@challenge.example', 'ssh learner@challenge.example -p 2222'], hint: 'SSH uses lowercase -p for the destination port.', explain: 'The command names the authorized user, host, and nonstandard port.' },
    { title: 'Search Every Text File Safely', brief: 'Loop over .txt files and print filename plus matching picoCTF lines.', artifact: '$ _', prompt: 'Enter the loop.', answers: ['for f in *.txt; do grep -H "picoCTF" "$f"; done', "for f in *.txt; do grep -H 'picoCTF' \"$f\"; done", 'for f in *.txt; do grep -H picoCTF "$f"; done'], hint: 'Use for f in *.txt, quote "$f", and let grep -H show filenames.', explain: 'The glob supplies files, the quoted variable preserves each filename, and grep -H labels matches.' }
  ];

  const lessons = units.flatMap((unit, unitIndex) => unit.lessons.map((item) => ({ ...item, unit: unitIndex + 1, unitTitle: unit.title })));
  lessons.forEach((item, index) => { item.number = index + 1; });
  return { course: 'Bash for Cybersecurity', slug: 'bash-for-cybersecurity', units, lessons, labs, labTitle: 'Bash CTF Workflow Lab', labDescription: 'A checked terminal-command lab covering navigation, search, representations, permissions, and remote challenge setup.' };
}));
